export function ToolLogo({ name, size = 36, className }: ToolLogoProps) {
  if (name === "Cloudflare") {
    const cloudflareLogo = logos["Cloudflare"];

    return (
      <span
        role="img"
        aria-label="Cloudflare logo"
        className={["inline-flex items-center gap-1.5", className].filter(Boolean).join(" ")}
      >
        <svg viewBox="0 0 24 24" width={size} height={size} fill="#F38020" aria-hidden="true">
          {cloudflareLogo?.kind === "vector" ? cloudflareLogo.content : null}
        </svg>
        <span className="text-[13px] font-black uppercase tracking-[0.08em] text-[#404041]">
          Cloudflare
        </span>
      </span>
    );
  }

  const logo = logos[name];
  if (!logo) return null;

  if (logo.kind === "raster") {
    return (
      <img
        src={logo.src}
        alt={`${name} logo`}
        width={size}
        height={size}
        loading="lazy"
        className={`${className ?? ""} object-contain`.trim()}
      />
    );
  }

  return (
    <svg
      viewBox={logo.viewBox}
      width={size}
      height={size}
      fill={logo.fill === "none" ? undefined : logo.fill}
      role="img"
      aria-label={`${name} logo`}
      className={className}
    >
      {logo.content}
    </svg>
  );
}
